import { describeSimulation } from '../lib/scenarioView.js';
import { Badge, Card } from './ui.jsx';

const BANNER_TONES = {
  warn: 'bg-warn-soft text-warn',
  success: 'bg-success-soft text-success',
  danger: 'bg-danger-soft text-danger',
  neutral: 'bg-surface-2 text-muted',
};

/**
 * Shows the outcome of one simulation: a titled banner with the plain-English explanation from the
 * API, the original and rerouted paths, and before/after numbers with the change. All wording
 * comes from the server's deterministic result, nothing here is generated by AI.
 */
export default function SimulationSummary({ simulation, stale = false }) {
  const view = describeSimulation(simulation);
  if (!view) return null;

  return (
    <section aria-label="Simulation result" className="flex flex-col gap-4">
      <div role="status" className={`rounded-xl p-4 ${BANNER_TONES[view.tone]}`}>
        <h2 className="text-base font-bold">{view.title}</h2>
        <p className="mt-1 text-sm text-fg">{view.explanation}</p>
        {stale && <p className="mt-1 text-xs text-muted">Updating for the new choice...</p>}
      </div>

      {view.rows.length > 0 && (
        <dl className="grid grid-cols-1 gap-3 sm:grid-cols-3">
          {view.rows.map((row) => (
            <Card key={row.key} className="p-3">
              <dt className="text-xs text-muted">{row.label}</dt>
              <dd className="mt-1 flex flex-col gap-1">
                <span className="font-mono text-sm">
                  <span className="text-muted">{row.before}</span>
                  <span aria-hidden="true"> to </span>
                  <span className="sr-only"> changed to </span>
                  <span className="font-semibold">{row.after}</span>
                </span>
                <Badge tone={row.tone} className="w-fit">
                  {row.delta}
                </Badge>
              </dd>
            </Card>
          ))}
        </dl>
      )}

      {view.original && (
        <ul className="flex flex-col gap-1 text-sm">
          <li>
            <span className="font-semibold">Original route: </span>
            {view.original}
          </li>
          {view.rerouted && (
            <li>
              <span className="font-semibold">Rerouted: </span>
              {view.rerouted}
            </li>
          )}
        </ul>
      )}

      {view.notice && <p className="text-xs text-muted">{view.notice}</p>}
    </section>
  );
}
